import { wordFrequencies } from "@api/text-stats";

export function topWords(text, count) {
	return Object.entries(wordFrequencies(text))
		.map(([word, times]) => ({ word, count: times }))
		.sort((a, b) => b.count - a.count)
		.slice(0, count);
}

export function report(text, count) {
	return topWords(text, count).map(({ word, count }) => `${word}: ${count}`).join("\n");
}
